from machine import I2C, Pin
import time
i2c = I2C({I2C_ID}, scl=Pin({SCL}), sda=Pin({SDA}))
def crc8(data):
    c = 0
    for b in data:
        c ^= b
        for _ in range(8):
            c = ((c << 1) ^ 0x07) & 0xFF if c & 0x80 else (c << 1) & 0xFF
    return c
def read_word(cmd):
    r = i2c.readfrom_mem(0x0B, cmd, 3)
    if crc8(bytes([0x16, cmd, 0x17, r[0], r[1]])) != r[2]:
        raise OSError('CRC')
    return r[0] | (r[1] << 8)
while True:
    print('V=%d' % read_word(0x09))
    time.sleep_ms(500)
